function months(years){ return Math.round(years*12); }
function project(C0, m, r, years){
  var M=months(years); var rm=r/12;
  if(rm===0) return C0 + m*M;
  var a=Math.pow(1+rm, M);
  return C0*a + m*(a-1)/rm;
}
function requiredMonthly(C0, target, r, years){
  var M=months(years); var rm=r/12;
  if(rm===0) return (target-C0)/M;
  var a=Math.pow(1+rm, M);
  return (target - C0*a)*rm/(a-1);
}
var EXPORTS={project:project, requiredMonthly:requiredMonthly, months:months};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.RetireForgePure = EXPORTS; }
